#!/usr/bin/env python3
"""Rebuild a dependency-free GitHub Pages site from data/content.json.
Run: python3 build.py
"""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json, csv

ROOT = Path(__file__).resolve().parent
D = json.loads((ROOT/'data/content.json').read_text(encoding='utf-8'))
S = D['site']
PUB = {p['id']:p for p in D['publications']}


def e(v): return escape(str(v), quote=True)

def paper_link(p):
    return ('https://doi.org/' + p['doi']) if p['doi'] else (p.get('url') or ('https://scholar.google.com/scholar?q=' + quote(p['title'])))

def arrow(): return '<span class="arrow" aria-hidden="true">↗</span>'

def pill(label, extra=''): return '<span class="pill '+e(extra)+'">'+e(label)+'</span>'

def button(text, href, klass='btn-primary', icon='↗', extra=''):
    return f'<a class="btn {klass}" href="{e(href)}" {extra}><span>{e(text)}</span><span aria-hidden="true">{icon}</span></a>'

def section_head(kicker,title,description='',more=''):
    return f'''<div class="section-head"><div><div class="eyebrow"><span class="eyebrow-line"></span>{e(kicker)}</div><h2>{title}</h2>{f'<p class="section-desc">{description}</p>' if description else ''}</div>{more}</div>'''

def nav(active):
    pages=[('Home','index.html'),('Research','research.html'),('Publications','publications.html'),('Gallery','gallery.html'),('News & Media','news.html'),('About & CV','about.html')]
    anchors=[]
    nav_links=''.join(f'<a class="nav-link {"active" if active==n else ""}" href="{url}" {"aria-current=page" if active==n else ""}>{n}</a>' for n,url in pages+anchors)
    return f'''<header class="site-header" id="top"><div class="shell header-inner">
    <a class="brand" href="index.html" aria-label="Swarnamouli Majumdar — homepage"><span class="brand-mark">sm<span>.</span></span><span class="brand-word">Swarnamouli <strong>Majumdar</strong></span></a>
    <nav class="desktop-nav" aria-label="Main navigation">{nav_links}</nav>
    <div class="header-actions"><button class="theme-toggle" data-theme-toggle type="button" title="Toggle color theme" aria-label="Toggle color theme"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M20.1 15.8A8.5 8.5 0 0 1 8.2 3.9 8.5 8.5 0 1 0 20.1 15.8Z"/></svg></button><a href="index.html#contact" class="header-contact">Connect <span aria-hidden="true">↗</span></a><button class="menu-toggle" data-menu-toggle type="button" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open menu"><span></span><span></span><span></span></button></div>
    </div><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" hidden>{nav_links}<a href="index.html#contact">Connect ↗</a></nav></header>'''

def footer():
    return f'''<footer class="footer"><div class="shell"><div class="footer-top"><div><a class="footer-name" href="index.html">Swarnamouli Majumdar<span>.</span></a><p>Research, technology, and purpose—<br>at the intersection of intelligent systems and public impact.</p></div><div class="footer-links"><a href="research.html">Research</a><a href="publications.html">Publications</a><a href="news.html">News & Media</a><a href="gallery.html">Gallery</a><a href="about.html">Academic & professional CV</a><a href="{e(S['scholar'])}" target="_blank" rel="noopener noreferrer">Google Scholar ↗</a><a href="https://orcid.org/{e(S['orcid'])}" target="_blank" rel="noopener noreferrer">ORCID ↗</a><a href="{e(S['linkedin'])}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div></div><div class="footer-bottom"><span>© <span id="copyright-year">2026</span> Swarnamouli Majumdar. All rights reserved.</span><span>Made for curious minds and meaningful collaborations.</span><a href="#top">Back to top ↑</a></div></div></footer>'''

def layout(page, title, desc, content, jsonld=''):
    full_title = title + ' | Swarnamouli Majumdar' if title != 'Home' else 'Swarnamouli Majumdar | AI Researcher, Founder & Public-Safety Technologist'
    structured = jsonld or json.dumps({
        '@context':'https://schema.org','@type':'Person','name':S['name'],
        'url':S['website'],'email':'mailto:'+S['email'],'jobTitle':'Ph.D. Candidate & Founder, Zenext AI',
        'affiliation': [{'@type':'CollegeOrUniversity','name':'Concordia University'},{'@type':'Organization','name':'Zenext AI'}],
        'sameAs':['https://orcid.org/'+S['orcid'],S['linkedin']]
    },ensure_ascii=False)
    return f'''<!doctype html><html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f9f7f3"><meta name="color-scheme" content="light dark">
<title>{e(full_title)}</title><meta name="description" content="{e(desc)}"><meta name="author" content="Swarnamouli Majumdar">
<meta property="og:type" content="website"><meta property="og:title" content="{e(full_title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="https://swarnamouli.github.io/{'index.html' if page=='Home' else ('gallery' if page == 'Gallery' else page.lower().split(' ')[0])+'.html'}"><meta property="og:image" content="https://swarnamouli.github.io/assets/og-card.png">
<meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="https://swarnamouli.github.io/{'index.html' if page=='Home' else ('gallery' if page == 'Gallery' else page.lower().split(' ')[0])+'.html'}">
<link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script>try{{let t=localStorage.getItem('sm-theme');if(t)document.documentElement.dataset.theme=t}}catch(e){{}}</script>
<script type="application/ld+json">{structured}</script><script src="assets/main.js" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a>{nav('About & CV' if page == 'About' else ('News & Media' if page == 'News' else page))}<main id="main">{content}</main>{footer()}</body></html>'''


def pub_card(p,compact=False):
    link=paper_link(p)
    action = 'View publisher / DOI' if p['doi'] else 'Find on Google Scholar'
    return f'''<article class="pub-card {'pub-card-compact' if compact else ''}" data-year="{p['year']}" data-type="{e(p['type'])}" data-topic="{e(p['topic'])}" data-search="{e((p['title']+' '+p['venue']+' '+p['topic']).lower())}">
    <div class="pub-meta">{pill(str(p['year']))}{pill(p['type'], 'pill-subtle')}<span class="pub-topic">{e(p['topic'])}</span></div>
    <h3><a href="{e(link)}" target="_blank" rel="noopener noreferrer">{e(p['title'])}</a></h3>
    <p class="pub-venue">{e(p['venue'])}</p>
    <div class="pub-actions"><a class="text-link" href="{e(link)}" target="_blank" rel="noopener noreferrer">{e(action)} {arrow()}</a>{(f'<button class="copy-button" data-copy="https://doi.org/{e(p["doi"])}" type="button" title="Copy DOI link" aria-label="Copy DOI link">Copy DOI</button>') if p['doi'] else ''}</div>
    </article>'''


def research_card(r):
    return f'''<article class="research-card reveal"><span class="research-card-number">{r['number']} / {e(r['label'])}</span><div class="research-icon research-icon-{e(r['key'])}" aria-hidden="true"><span></span><span></span><span></span></div><h3>{e(r['title'])}</h3><p>{e(r['summary'])}</p><a class="text-link" href="research.html#{e(r['key'])}">Explore direction {arrow()}</a></article>'''


def project_card(p):
    pub=PUB[p['link_id']]
    return f'''<article class="project-card reveal"><div class="project-art art-{e(p['number'])}"><div class="project-art-number">{e(p['number'])}</div><div class="art-orbit art-orbit-1"></div><div class="art-orbit art-orbit-2"></div><div class="art-center">{e(p['name'][:1])}</div><span class="art-footnote">{e(p['category'])}</span></div><div class="project-body"><p class="card-overline">{e(p['eyebrow'])}</p><h3>{e(p['name'])}</h3><h4>{e(p['title'])}</h4><p>{e(p['description'])}</p><a href="{e(paper_link(pub))}" target="_blank" rel="noopener noreferrer" class="text-link">Related research {arrow()}</a></div></article>'''


def gallery_section():
    """Optional photo gallery, only visible if gallery entries are added to JSON."""
    gallery = [g for g in D.get('gallery', []) if g['category'] in ('Conference','Awards','Innovation') and ('ICACIML' in g['title'] or 'CCNCPS' in g['title'] or 'Zenext AI' in g['title'])][:3]
    if not gallery:
        return ''
    items = ''.join(f'<figure class="gallery-item"><img src="{e(g.get("thumb",g["image"]))}" alt="{e(g["alt"])}" loading="lazy"><figcaption><strong>{e(g["title"])}</strong><span>{e(g.get("caption", ""))}</span></figcaption></figure>' for g in gallery)
    return f'<section class="section soft-section" id="gallery"><div class="shell">{section_head("MOMENTS / IN THE FIELD", "Beyond the <em>research paper.</em>", "Talks, collaborations, and technology work along the way.")}<div class="gallery-grid">{items}</div><p class="gallery-more"><a class="text-link" href="gallery.html">Open the interactive photo gallery ↗</a></p></div></section>'


def media_related(item):
    links = item.get('related', [])
    if not links: return ''
    return '<div class="media-related">' + ''.join(f'<a href="{e(link["url"])}" target="_blank" rel="noopener noreferrer">{e(link["label"])} {arrow()}</a>' for link in links) + '</div>'


def media_rail(item):
    return f'''<article class="media-rail-story"><p class="media-rail-meta">{e(item['outlet'])} <span>· {e(item['date_label'])}</span></p><h3><a href="{e(item['url'])}" target="_blank" rel="noopener noreferrer">{e(item['title'])} <span aria-hidden="true">↗</span></a></h3><p>{e(item['summary'])}</p></article>'''


def media_card(item):
    return f'''<article class="media-card" data-media-category="{e(item['category'])}" data-media-search="{e((item['title']+' '+item['outlet']+' '+item['summary']).lower())}"><div class="media-card-head"><span class="media-outlet">{e(item['outlet'])}</span><span class="media-card-date">{e(item['date_label'])}</span></div><span class="media-card-type">{e(item['type'])}</span><h3><a href="{e(item['url'])}" target="_blank" rel="noopener noreferrer">{e(item['title'])}</a></h3><p>{e(item['summary'])}</p><div class="media-card-links"><a class="text-link" href="{e(item['url'])}" target="_blank" rel="noopener noreferrer">{('Listen to interview' if item['type']=='Podcast interview' else 'View original source')} {arrow()}</a>{media_related(item)}</div></article>'''


def news_page():
    items=D['media']
    news_items=''.join(media_card(x) for x in items)
    hero='''<section class="page-hero media-page-hero"><div class="shell"><div class="eyebrow"><span class="eyebrow-line"></span>NEWS / MEDIA / PUBLIC ENGAGEMENT</div><h1>Work that travels <em>further.</em></h1><p>A selected collection of media reports, interviews, university features, and public event listings connected to my research and work at Zenext AI. Each entry links to its original publisher or institution.</p><div class="media-masthead"><span>BIOENGINEER.ORG</span><span>SCIENMAG</span><span>URGENT COMMUNICATIONS</span><span>INDIANA UNIVERSITY</span><span>SMART FIREFIGHTING</span></div></div></section>'''
    content=f'''<section class="section shell media-index" id="media-archive">{section_head('THE ARCHIVE','Stories, conversations <em>& recognition.</em>','Browse verified sources and open each original story, interview, or event listing.')}<div class="media-filter-row"><div class="media-tabs" aria-label="Filter media mentions by source type"><button type="button" class="media-tab is-active" data-media-filter="all" aria-pressed="true">All</button><button type="button" class="media-tab" data-media-filter="coverage" aria-pressed="false">Coverage</button><button type="button" class="media-tab" data-media-filter="interviews" aria-pressed="false">Interviews & podcasts</button><button type="button" class="media-tab" data-media-filter="institutional" aria-pressed="false">Institutional features</button><button type="button" class="media-tab" data-media-filter="events" aria-pressed="false">Events</button></div><label class="media-search-wrap"><span class="sr-only">Search news and media</span><input type="search" id="media-search" placeholder="Search outlets or topics…" autocomplete="off"></label></div><p class="media-count" aria-live="polite"><span id="media-count">{len(items)}</span> selected items</p><div class="media-card-grid" id="media-card-grid">{news_items}</div><p class="no-results" id="media-empty" hidden>No items match your search. Try another keyword or category.</p><div class="media-source-note"><strong>Editorial note</strong><p>News articles, first-person interviews, university stories, government recognition and conference program listings are labeled by type. Bioengineer.org and Scienmag carried the same October 2026 Zero Trust article; it appears as one coverage item with both publication links. The material summarizes published work and does not imply that proposed research architectures have been validated or deployed.</p><p>The archive below mixes third-party coverage, official conference listings, and selected public posts so the source of each item is easy to interpret. <a href="gallery.html">Browse conference photographs and speaking highlights</a>.</p><p>Last reviewed: 10 November 2026. This page is curated rather than a live news feed.</p></div></section>'''
    return layout('News', 'News & Media','News and media appearances featuring Swarnamouli Majumdar, Zenext AI, public-safety AI research, autonomous drone governance and human-centered innovation.',hero+content)


def home():
    featured=[p for p in D['publications'] if p['featured']][:4]
    news=D['media']
    hero=f'''<section class="hero shell"><div class="hero-content"><div class="eyebrow"><span class="eyebrow-line"></span>HELLO, I'M SWARNAMOULI</div><h1>Intelligence for<br><em>the moments</em><br>that matter<span class="period">.</span></h1><p class="hero-lead">I study how artificial intelligence and autonomous systems can improve real-world decisions—especially where public safety, human trust, and technology intersect.</p><div class="hero-tags"><span>AI & MACHINE LEARNING</span><span>AUTONOMOUS SYSTEMS</span><span>PUBLIC SAFETY</span></div><div class="hero-buttons">{button('Explore my research','research.html','btn-primary','↗')}{button('View publications','publications.html','btn-secondary','→')}</div><div class="hero-social"><a href="{e(S['linkedin'])}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="{e(S['scholar'])}" target="_blank" rel="noopener noreferrer">Google Scholar ↗</a><a href="https://orcid.org/{e(S['orcid'])}" target="_blank" rel="noopener noreferrer">ORCID ↗</a><a href="mailto:{e(S['email'])}">Email ↗</a></div></div>
    <div class="hero-visual"><div class="hero-visual-deco deco-a"></div><div class="hero-visual-deco deco-b"></div><figure class="portrait-frame"><img src="{e(S.get('portrait','assets/avatar.svg'))}" alt="Portrait of Swarnamouli Majumdar" loading="eager"><figcaption class="portrait-bio-caption"><strong>Swarnamouli Majumdar</strong><span>Ph.D. candidate at Concordia University and Founder &amp; CEO of Zenext AI, advancing AI and autonomous systems for public safety.</span></figcaption><span class="portrait-frame-corner"></span></figure><div class="role-float"><span class="role-dot"></span><div><strong>Ph.D. Candidate</strong><small>Concordia University</small></div></div><div class="founder-float"><strong>Founder & CEO</strong><span>Zenext AI</span><span aria-hidden="true">↗</span></div></div></section>'''
    strip='''<div class="hero-strip"><div class="shell strip-inner"><div><strong>Research</strong><span>AI · Autonomy · Human oversight</span></div><div><strong>Innovation</strong><span>Voice-first emergency technology</span></div><div><strong>Perspective</strong><span>Academia × Industry × Public impact</span></div></div></div>'''
    quicknav='''<section class="shell quick-intro"><div class="eyebrow"><span class="eyebrow-line"></span>EXPLORE THE PORTFOLIO</div><p class="quick-text">Choose a section. Research, publications, and presentations each have their own space.</p><div class="quick-nav"><a href="research.html"><small>01 / EXPLORE</small><strong>Research programs</strong><b aria-hidden="true">↗</b></a><a href="publications.html"><small>02 / READ</small><strong>Publications & DOI links</strong><b aria-hidden="true">↗</b></a><a href="gallery.html"><small>03 / SEE</small><strong>Conference gallery</strong><b aria-hidden="true">↗</b></a><a href="about.html"><small>04 / LEARN</small><strong>Career & recognition</strong><b aria-hidden="true">↗</b></a></div></section>'''
    about=f'''<section class="section shell" id="about">{section_head('01 / About me','Where rigorous research <em>meets</em> real-world need.')}<div class="about-grid"><div class="about-statement"><p>My work begins with a simple conviction: <span>the most valuable technology is technology that serves people.</span></p><div class="about-statement-bottom">RESEARCHER <span>✦</span> ENGINEER <span>✦</span> ENTREPRENEUR</div></div><div class="about-copy"><p>I'm a Ph.D. candidate in Information Systems Engineering at <strong>Concordia University</strong> and the <strong>Founder & CEO of Zenext AI</strong>. My research explores artificial intelligence, machine learning, reinforcement learning, autonomous vehicles, and connected systems—with a particular focus on public-safety applications.</p><p>Across industry, research, and entrepreneurship, I have worked on the challenges of turning complex data and algorithms into systems that people can understand, operate, and trust. That perspective informs my work on adaptive routing, medical drones, voice-first interfaces, and accountable AI.</p><a class="text-link" href="about.html">More about my journey {arrow()}</a></div></div></section>'''
    research=f'''<section class="section soft-section" id="research"><div class="shell">{section_head('02 / Research agenda','Questions worth <em>working on.</em>','Explore three priority themes here; the full research page covers all five directions.',f'<a class="head-link" href="research.html">View research program →</a>')}<div class="research-grid">{''.join(research_card(r) for r in D['research'][:3])}</div></div></section>'''
    lead_news=news[0]
    home_side=[next(n for n in news if n["id"]==i) for i in ("skysentience-scienmag-2026", "smart-firefighting-2024", "urgent-comms-2024") if any(n["id"]==i for n in news)]
    feature_links=media_related(lead_news)
    newssec=f'''<section class="section shell" id="news">{section_head('03 / News & media','The work, <em>in the world.</em>','Selected reporting, interviews and institutional features about my research and Zenext AI.', '<a class="head-link" href="news.html">Open media archive →</a>')}<div class="media-home-grid"><article class="media-main-feature reveal"><div class="media-feature-top"><span class="media-feature-icon" aria-hidden="true">S<span>·</span>M</span><span class="media-feature-kicker">FEATURED RESEARCH COVERAGE</span></div><div><div class="media-byline"><span>{e(lead_news['outlet'])}</span><span>{e(lead_news['date_label'])}</span></div><h3><a href="{e(lead_news['url'])}" target="_blank" rel="noopener noreferrer">{e(lead_news['title'])}</a></h3><p>{e(lead_news['summary'])}</p><a class="media-read-link" href="{e(lead_news['url'])}" target="_blank" rel="noopener noreferrer">Read the article {arrow()}</a></div>{feature_links}</article><div class="media-home-rail">{''.join(media_rail(n) for n in home_side)}<a class="media-archive-link" href="news.html"><span>Explore the complete news archive</span><span aria-hidden="true">↗</span></a></div></div><p class="media-integrity-note">External reporting and interviews are shown separately from university, government, and conference listings. Linked research descriptions identify conceptual work as such.</p></section>'''
    publications=f'''<section class="section soft-section" id="publications"><div class="shell">{section_head('04 / Selected publications','Research, <em>in print.</em>','A selection of journal articles from my broader publication record.',f'<a class="head-link" href="publications.html">Browse all selected work →</a>')}<div class="pub-feature-grid">{''.join(pub_card(p,True) for p in featured)}</div><p class="section-footnote">For the complete bibliography and latest citations, visit <a href="{e(S['scholar'])}" target="_blank" rel="noopener noreferrer">Google Scholar</a> or <a href="{e(S['scholar'])}" target="_blank" rel="noopener noreferrer">Google Scholar ↗</a><a href="https://orcid.org/{e(S['orcid'])}" target="_blank" rel="noopener noreferrer">ORCID</a> and <a href="https://www.scopus.com/authid/detail.uri?authorId={e(S['scopus'])}" target="_blank" rel="noopener noreferrer">Scopus</a>.</p></div></section>'''
    innovation=f'''<section class="section shell" id="innovation">{section_head('05 / Technology & innovation','From research idea <em>to application.</em>','Selected research frameworks and R&D directions. Descriptions distinguish published studies and concepts from deployed products.')}<div class="projects-grid">{''.join(project_card(p) for p in D['projects'])}</div></section>'''
    awards=D['awards'][:4]
    recognition=f'''<section class="section acclaim-section" id="recognition"><div class="shell acclaim-grid"><div><div class="eyebrow eyebrow-light"><span class="eyebrow-line"></span>06 / RECOGNITION</div><h2>Work with a<br><em>wider impact.</em></h2><p>Research honors, national innovation recognition, and competitive selection reflect a commitment to relevant, responsible technology.</p><a href="about.html#awards" class="light-link">View all recognition <span aria-hidden="true">↗</span></a></div><div class="award-list">{''.join(f'<div class="award-row"><span>{e(a["year"])}</span><div><h3>{e(a["name"])}</h3><p>{e(a["detail"])}</p></div><span aria-hidden="true">↗</span></div>' for a in awards)}</div></div></section>'''
    speaking=f'''<section class="section shell" id="speaking">{section_head('07 / PRESENTATIONS & SERVICE','Research in <em>conversation.</em>','I value sharing ideas across scientific conferences, technology forums, and practitioner communities.')}
    <div class="speaking-grid"><article class="speaking-feature speaking-feature-photo"><img src="assets/photos/icaciml-2026-keynote.jpg" loading="lazy" alt="Swarnamouli Majumdar delivering a keynote at ICACIML 2026"><div class="speaking-feature-copy"><p class="card-overline">KEYNOTE & INDUSTRY PANEL · MARCH 2026</p><h3>AI for Safer Cities and Communities</h3><p>ICACIML 2026 at ICFAI Tech, Hyderabad. Keynote speaking and a panel on the future of human intelligence.</p><a class="text-link" href="gallery.html#icaciml-2026">Explore talks & photographs ↗</a></div></article><div class="speaking-list"><div><span>2025</span><section><strong>Advanced Information Networking and Applications (AINA)</strong><p>Smart IoT-enabled autonomous vehicles for next-generation public safety.</p></section></div><div><span>2025</span><section><strong>IEEE ISNCC</strong><p>Industry Forum & Exhibition Chair, connecting academic and practitioner communities.</p></section></div><div><span>2024</span><section><strong>NIST / PSCR 5×5 Summit</strong><p>Public-safety technology research and invited speaking engagement.</p></section></div></div></div><p class="speaking-more"><a class="text-link" href="gallery.html">See conference talks, recognitions & photo gallery ↗</a></p></section>'''
    exp=f'''<section class="section shell" id="experience">{section_head('08 / Professional path','A career spanning <em>multiple worlds.</em>','Research and entrepreneurship grounded in hands-on experience with data science, software systems, autonomous mobility, and industry R&D.',f'<a class="head-link" href="about.html#experience">Full experience →</a>')}<div class="experience-preview"><div class="exp-logo-panel"><span>2011</span><div class="exp-line"></div><span>2026</span><p>Research. Industry. Innovation.</p></div><div class="exp-preview-list">{''.join(f'<div class="exp-preview-row"><span>{e(x["period"])}</span><div><strong>{e(x["role"])}</strong><p>{e(x["organization"])}</p></div></div>' for x in D['experience'][:4])}</div></div></section>'''
    teaching=f'''<section class="section soft-section"><div class="shell teaching-grid"><div><div class="eyebrow"><span class="eyebrow-line"></span>09 / TEACHING & COLLABORATION</div><h2>Learning is also<br><em>a shared endeavor.</em></h2></div><div><p>My teaching interests include programming, software engineering, data science, AI, machine learning, databases, intelligent systems, and responsible computing. I value project-based learning that combines clear fundamentals with real technical problems.</p><p>I welcome research collaborations, interdisciplinary projects, invited talks, and conversations with students, industry partners, and public-sector practitioners.</p><a class="text-link" href="about.html#teaching">Teaching & academic service {arrow()}</a></div></div></section>'''
    contact=f'''<section class="contact-section" id="contact"><div class="shell contact-inner"><div><div class="eyebrow"><span class="eyebrow-line"></span>LET'S CONNECT</div><h2>Have a question,<br>a challenge, <em>or an idea?</em></h2><p>I'm always interested in thoughtful conversations about research, intelligent technology, and public impact.</p></div><div class="contact-aside">{button('Send an email','mailto:'+S['email'],'btn-dark','↗')}<button type="button" class="btn btn-secondary copy-contact" data-copy-email="{e(S['email'])}">Copy email address ↗</button><a href="{e(S['linkedin'])}" target="_blank" rel="noopener noreferrer">Message on LinkedIn <span aria-hidden="true">↗</span></a><small class="contact-email-text">{e(S['email'])}</small></div></div></section>'''
    return layout('Home','Home','Swarnamouli Majumdar is a Ph.D. researcher at Concordia University and Founder & CEO of Zenext AI, working on AI, autonomous systems, and public safety.',hero+strip+quicknav+about+research+newssec+publications+gallery_section()+contact)


def research_page():
    head='''<section class="page-hero page-hero-research"><div class="shell page-hero-grid"><div><div class="eyebrow"><span class="eyebrow-line"></span>RESEARCH / THE BIG QUESTIONS</div><h1>Intelligent systems.<br><em>Human consequences.</em></h1><p>My research connects algorithmic methods with the social, operational, and engineering realities of systems used in public safety and connected cities.</p><div class="page-hero-actions">'''+button('Explore publications','publications.html','btn-primary','↗')+'''</div></div><div class="diagram-panel"><div class="diagram-label">RESEARCH AT THE INTERSECTION OF</div><svg viewBox="0 0 460 400" role="img" aria-label="Diagram linking intelligent autonomy, public safety, human oversight, and connected systems"><circle cx="230" cy="195" r="130" fill="none" stroke="currentColor" stroke-opacity=".12" stroke-width="1"/><circle cx="230" cy="195" r="75" fill="none" stroke="currentColor" stroke-opacity=".18" stroke-width="1"/><path d="M230 195L230 42M230 195L387 195M230 195L230 347M230 195L73 195" stroke="currentColor" stroke-opacity=".25" stroke-dasharray="5 7"/><circle cx="230" cy="195" r="42" fill="#a8696e"/><text x="230" y="192" text-anchor="middle" fill="#fff" font-size="13" font-family="sans-serif">HUMAN</text><text x="230" y="210" text-anchor="middle" fill="#fff" font-size="13" font-family="sans-serif">IMPACT</text><circle cx="230" cy="42" r="9" fill="#ac746d"/><circle cx="387" cy="195" r="9" fill="#ac746d"/><circle cx="230" cy="347" r="9" fill="#ac746d"/><circle cx="73" cy="195" r="9" fill="#ac746d"/><text x="230" y="24" text-anchor="middle" font-size="12" fill="currentColor">AUTONOMY</text><text x="230" y="376" text-anchor="middle" font-size="12" fill="currentColor">OVERSIGHT</text><text x="70" y="165" text-anchor="middle" font-size="12" fill="currentColor">PUBLIC</text><text x="70" y="182" text-anchor="middle" font-size="12" fill="currentColor">SAFETY</text><text x="389" y="164" text-anchor="middle" font-size="12" fill="currentColor">CONNECTED</text><text x="389" y="181" text-anchor="middle" font-size="12" fill="currentColor">SYSTEMS</text></svg></div></div></section>'''
    intro='''<section class="section shell narrow-intro"><div class="eyebrow"><span class="eyebrow-line"></span>THE RESEARCH PHILOSOPHY</div><p class="large-quote">A capable intelligent system is only useful when its actions are <em>understandable, testable, and appropriate to the people who rely on it.</em></p><div class="two-col-body"><p>My work ranges from machine learning and graph-based methods to cyber-physical architectures and human–AI interaction. It is motivated by real questions: how to handle uncertain information, coordinate scarce resources, plan in changing environments, and preserve human judgment.</p><p>These areas overlap across emergency medicine, firefighting, autonomous vehicles, urban operations, and first-responder communications. I use computational methods, system models, and applied research to examine what technology can—and cannot yet—reliably do.</p></div></section>'''
    rows=''
    for i,r in enumerate(D['research']):
        pubs=''.join(f'<li><a href="{e(paper_link(PUB[pid]))}" target="_blank" rel="noopener noreferrer">{e(PUB[pid]["title"])} ↗</a></li>' for pid in r['publication_ids'])
        rows+=f'''<article class="research-deep" id="{e(r['key'])}"><div class="research-deep-label"><span>{r['number']}</span><p>{e(r['label'])}</p></div><div class="research-deep-main"><h2>{e(r['title'])}</h2><p class="deep-lead">{e(r['summary'])}</p><div class="research-question"><span>THE QUESTION</span><p>{e(r['question'])}</p></div><div class="deep-columns"><div><h3>Methods & interests</h3><div class="method-list">{''.join(pill(m,'method-pill') for m in r['methods'])}</div></div><div><h3>Research contribution</h3><p>{e(r['contribution'])}</p></div></div><details class="related-papers"><summary>Related publications <span aria-hidden="true">+</span></summary><ul>{pubs}</ul></details></div></article>'''
    items=f'''<section class="section soft-section"><div class="shell">{section_head('RESEARCH THEMES','Five directions. <em>One purpose.</em>')}<div class="research-deep-list">{rows}</div></div></section>'''
    end=f'''<section class="section shell research-values">{section_head('RESEARCH PRACTICE','What guides <em>the work.</em>')}<div class="values-grid"><div><span>01</span><h3>Methodological rigor</h3><p>Testable models, transparent assumptions, and evaluations that distinguish conceptual frameworks from measured results.</p></div><div><span>02</span><h3>Human-centered decisions</h3><p>Systems designed to inform people rather than hide uncertainty or displace professional judgment.</p></div><div><span>03</span><h3>Real-world relevance</h3><p>Research questions connected to operational constraints, system reliability, interoperability, and public needs.</p></div></div></section><section class="research-end"><div class="shell"><h2>Interested in collaborating?</h2><p>Interdisciplinary research, student mentorship, and practical collaborations are important parts of my work.</p>{button('Connect with me','mailto:'+S['email'],'btn-primary','↗')}</div></section>'''
    return layout('Research','Research','Research programs in machine learning, intelligent autonomy, emergency response, trustworthy AI, and smart cities by Swarnamouli Majumdar.',head+intro+items+end)


def publications_page():
    unique_topics=list(dict.fromkeys(p['topic'] for p in D['publications']))
    items=''.join(pub_card(p) for p in D['publications'])
    head=f'''<section class="page-hero small-page-hero"><div class="shell"><div class="eyebrow"><span class="eyebrow-line"></span>PUBLICATIONS / RESEARCH LIBRARY</div><h1>Ideas made <em>public.</em></h1><p>A searchable collection of research papers with direct publisher and DOI links. The full, continuously updated bibliography is available on Google Scholar.</p><div class="pub-identity">{button('Google Scholar — full profile',S['scholar'],'btn-primary','↗','target="_blank" rel="noopener noreferrer"')}{button('View ORCID','https://orcid.org/'+S['orcid'],'btn-secondary','↗','target="_blank" rel="noopener noreferrer"')}{button('View Scopus','https://www.scopus.com/authid/detail.uri?authorId='+S['scopus'],'btn-secondary','↗','target="_blank" rel="noopener noreferrer"')}</div></div></section>'''
    main=f'''<section class="section shell publications-section"><div class="pub-intro"><div><p class="eyebrow"><span class="eyebrow-line"></span>RESEARCH LIBRARY</p><h2>Explore the collection.</h2></div><p>Search the indexed research collection below. Publisher links open individual papers; Google Scholar provides the comprehensive living record.</p></div>
    <div class="filter-bar"><label class="search-field"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.8" cy="10.8" r="7.1"/><path d="m16 16 5 5"/></svg><span class="sr-only">Search publications</span><input type="search" id="pub-search" placeholder="Search title, venue, or topic…" autocomplete="off"></label><label class="filter-select-label">Year <select id="pub-year"><option value="all">All years</option><option value="2026">2026</option><option value="2025">2025</option><option value="2024">2024</option><option value="2023">2023</option><option value="2022">2022</option></select></label><label class="filter-select-label">Type <select id="pub-type"><option value="all">All types</option><option value="Journal">Journal</option><option value="Conference">Conference</option><option value="Working paper">Working paper</option></select></label></div>
    <div class="topic-filters" aria-label="Filter publications by topic"><button class="topic-chip is-active" type="button" data-topic="all" aria-pressed="true">All topics</button>{''.join(f'<button class="topic-chip" type="button" data-topic="{e(t)}" aria-pressed="false">{e(t)}</button>' for t in unique_topics)}</div>
    <div class="pub-count" aria-live="polite"><span id="pub-visible">{len(D['publications'])}</span> selected works <span class="count-note">· Sorted newest first</span></div><div class="pub-results" id="pub-results">{items}</div><div id="no-results" class="no-results" hidden><h3>No publications match those filters.</h3><p>Try another year, topic, or search term.</p><button type="button" id="reset-filters" class="btn btn-secondary">Clear filters →</button></div>
    <div class="pub-disclaimer"><strong>About this list</strong><p>Publication metadata combines academic CV and verifiable publisher records. Items without independently confirmed publisher records are explicitly labeled as working papers. DOI links lead directly to published work; where a DOI was not supplied, “Find paper” opens a scholarly title search. For the complete, continuously updated set of papers, see <a href="{e(S['scholar'])}" target="_blank" rel="noopener noreferrer">my Google Scholar profile ↗</a>. The local collection is cross-checked against publisher and indexing records, but is not an automatic export of Scholar.</p><a class="text-link" href="data/publications.csv" download>Download this list as CSV ↓</a></div></section>'''
    return layout('Publications','Publications','Selected publications by Swarnamouli Majumdar in IEEE Access, Springer Nature journals, Applied Sciences, Electronics and IEEE conferences.',head+main)


def about_page():
    head=f'''<section class="page-hero about-page-hero"><div class="shell about-hero-grid"><div><div class="eyebrow"><span class="eyebrow-line"></span>ABOUT / ACADEMIC & PROFESSIONAL CV</div><h1>Curiosity, <em>with purpose.</em></h1><p>I am an AI researcher, technologist, and founder working where intelligent systems meet complex human challenges. My path has moved through software engineering, industry data science, autonomous vehicles, research, and public-safety innovation.</p>{button('Connect on LinkedIn',S['linkedin'],'btn-primary','↗')}</div><aside class="about-focus-panel" aria-label="Research and professional focus"><span class="about-focus-eyebrow">RESEARCH / INNOVATION / IMPACT</span><h2>Engineering intelligence for the public good.</h2><p>Research at Concordia University. Innovation through Zenext AI. A focus on AI, autonomous systems, and dependable technologies for first responders.</p><span class="about-focus-location">MONTRÉAL, CANADA</span></aside></div></section>'''
    bio=f'''<section class="section shell" id="biography">{section_head('BACKGROUND','A different kind <em>of perspective.</em>')}<div class="two-col-body about-biography"><p>I am pursuing my Ph.D. in Information Systems Engineering at Concordia University in Montréal, with research in artificial intelligence, machine learning, and autonomous decision support. My interests include reinforcement learning, intelligent transportation systems, human-supervised UAVs, and reliable software for critical settings.</p><p>As Founder and CEO of Zenext AI, I lead R&D focused on hands-free AI interfaces and connected technologies for first responders. Earlier roles with Motional, Cummins, State Street, System Soft Technologies, and other organizations shaped how I approach data, software, mobility, and cross-disciplinary problem solving. I aim to bridge research with technology that is understandable, testable, and socially relevant.</p></div><div class="profile-facts"><div><span>CURRENTLY</span><strong>Ph.D. Candidate</strong><small>Concordia University</small></div><div><span>ALSO</span><strong>Founder & CEO</strong><small>Zenext AI</small></div><div><span>RESEARCH FOCUS</span><strong>Intelligent Systems</strong><small>AI, autonomy & public safety</small></div><div><span>BASED IN</span><strong>Montréal</strong><small>Québec, Canada</small></div></div></section>'''
    exp=f'''<section class="section soft-section" id="experience"><div class="shell">{section_head('PROFESSIONAL EXPERIENCE','The work behind <em>the research.</em>','A non-linear journey across research leadership, engineering R&D, financial data science, and autonomous mobility.')}<div class="timeline">{''.join(f'<article class="timeline-item"><div class="timeline-when">{e(x["period"])}<span class="timeline-dot"></span></div><div class="timeline-content"><div class="timeline-type">{e(x["type"])}</div><h3>{e(x["role"])}</h3><p class="timeline-org">{e(x["organization"])} <span>· {e(x["location"])}</span></p><p>{e(x["description"])}</p></div></article>' for x in D['experience'])}</div></div></section>'''
    edu=f'''<section class="section shell" id="education">{section_head('EDUCATION','An interdisciplinary <em>foundation.</em>')}<div class="education-list">{''.join(f'<div class="education-row"><span>{e(x["year"])}</span><div><h3>{e(x["degree"])}</h3><p>{e(x["school"])}</p><small>{e(x["note"])}</small></div></div>' for x in D['education'])}</div></section>'''
    aw=f'''<section class="section soft-section" id="awards"><div class="shell">{section_head('RECOGNITION','Research & <em>innovation honors.</em>')}<div class="award-cards">{''.join(f'<article><span class="award-year">{e(x["year"])}</span><span class="award-kind">{e(x["kind"])}</span><h3>{e(x["name"])}</h3><p>{e(x["detail"])}</p></article>' for x in D['awards'])}</div></div></section>'''
    service=f'''<section class="section shell" id="teaching">{section_head('TEACHING, SERVICE & OUTREACH','Giving knowledge <em>back.</em>')}<div class="service-grid"><div><h3>Teaching interests</h3><p>Introductory programming, data structures and algorithms, database systems, software engineering, AI, machine learning, applied data science, IoT, human–computer interaction, and responsible computing.</p><p>My preferred approach combines progressive hands-on exercises, reproducible experiments, collaborative projects, and examples drawn from real systems.</p></div><div><h3>Academic service</h3><ul><li>Editorial Board Member, <em>International Journal of Robotics and Automation Technology</em> (since 2025)</li><li>Technical program committee and peer-review service across IEEE CCWC, IEEE World AI IoT Congress, and IEEE IEMCON</li><li>Industry Forum and Exhibition Chair, ISNCC 2025</li><li>Invited research and practitioner talks at IEEE, NIST/PSCR, and international academic events</li></ul></div></div></section>'''
    contact=f'''<section class="about-contact"><div class="shell"><div><span class="eyebrow">COLLABORATE / CONNECT</span><h2>Let's do meaningful work together.</h2></div><div><p>Research collaboration, teaching, technical speaking, interdisciplinary partnerships, and public-safety R&D.</p><a class="text-link" href="mailto:{e(S['email'])}">{e(S['email'])} {arrow()}</a></div></div></section>'''
    return layout('About','About & CV','Academic background, industry experience, awards, teaching, and career of Swarnamouli Majumdar, researcher and Founder of Zenext AI.',head+bio+exp+edu+aw+'''<section class="section shell about-award-photo"><div><span class="eyebrow">FROM THE ARCHIVE</span><h2>A moment of recognition.</h2><p>Receiving the Best Paper Award at InCIT 2025 for research on mission adaptation and distributed cognition.</p><a class="text-link" href="gallery.html#incit-2025">View award and photographs ↗</a></div><img src="assets/photos/incit-2025-award-ceremony.jpg" alt="Swarnamouli Majumdar receiving the InCIT 2025 Best Paper Award" loading="lazy"></section>'''+service+contact)



def gallery_page():
    categories=['All','Conference','Awards','Innovation','Talks']
    nav=''.join(f'<button type="button" class="gallery-filter {"is-active" if k=="All" else ""}" data-gallery-filter="{e(k)}" aria-pressed="{str(k=="All").lower()}">{e("All photos" if k=="All" else k)}</button>' for k in categories)
    thumbs=[]
    for g in D.get('gallery',[]):
        thumbs.append(f'''<button type="button" class="gallery-tile" data-gallery-category="{e(g['category'])}" data-gallery-search="{e((g['title']+' '+g['caption']).lower())}" data-full-image="{e(g['image'])}" data-gallery-title="{e(g['title'])}" data-gallery-caption="{e(g['caption'])}" aria-label="Open photo: {e(g['title'])}"><span class="gallery-tile-image"><img src="{e(g['thumb'])}" loading="lazy" width="720" height="470" alt="{e(g['alt'])}"></span><span class="gallery-tile-copy"><strong>{e(g['title'])}</strong><small>{e(g['caption'])}</small></span></button>''')
    hero='''<section class="page-hero gallery-hero"><div class="shell"><div class="eyebrow"><span class="eyebrow-line"></span>PHOTO JOURNAL / CONFERENCES / PUBLIC SAFETY</div><h1>Research, <em>in action.</em></h1><p>Conferences, awards, university talks and hands-on demonstrations—captured in a concise photo journal. Select a thumbnail to see the full image and story.</p><div class="gallery-highlights"><a href="publications.html">Explore the papers ↗</a><a href="about.html#awards">Awards &amp; recognition ↗</a><a href="news.html">News &amp; media ↗</a></div></div></section>'''
    content=f'''<section class="section shell compact-gallery"><div class="gallery-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span>THE GALLERY</div><h2>Moments that tell <em>the story.</em></h2><p>Browse {len(D.get('gallery',[]))} photographs. All images load as lightweight thumbnails.</p></div><label class="gallery-search"><span class="sr-only">Search gallery photos</span><input type="search" id="gallery-search" placeholder="Find a conference or event…" autocomplete="off"></label></div><div class="gallery-filters" aria-label="Filter gallery by event type">{nav}</div><p class="gallery-count" aria-live="polite"><span id="gallery-visible">{len(D.get('gallery',[]))}</span> photos</p><div class="compact-gallery-grid" id="gallery-grid">{''.join(thumbs)}</div><p class="gallery-empty" id="gallery-empty" hidden>No photos match these filters.</p></section>
    <dialog class="gallery-dialog" id="gallery-dialog" aria-label="Photograph viewer"><button type="button" class="gallery-dialog-close" id="gallery-close" aria-label="Close photo viewer">×</button><div class="gallery-dialog-frame"><img id="gallery-dialog-image" alt=""><div class="gallery-dialog-info"><h3 id="gallery-dialog-title"></h3><p id="gallery-dialog-caption"></p><div class="gallery-dialog-actions"><button type="button" id="gallery-prev">← Previous</button><span id="gallery-position"></span><button type="button" id="gallery-next">Next →</button></div></div></div></dialog>'''
    return layout('Gallery','Gallery','Photo journal of academic conferences, invited talks, awards, and Zenext AI demonstrations.',hero+content)

def speaking_page():
    return gallery_page()

def main():
    for name,body in [('index.html',home()),('research.html',research_page()),('publications.html',publications_page()),('news.html',news_page()),('about.html',about_page()),('gallery.html',gallery_page()),('speaking.html',gallery_page())]:
        (ROOT/name).write_text(body,encoding='utf-8')
        print('built',name)
    with (ROOT/'data/publications.csv').open('w',newline='',encoding='utf-8') as out:
        writer=csv.DictWriter(out,fieldnames=['year','type','topic','title','venue','doi','url'])
        writer.writeheader()
        for p in D['publications']:
            writer.writerow({**{k:p[k] for k in ['year','type','topic','title','venue','doi']},'url':paper_link(p)})

if __name__=='__main__':main()
